from lxml import objectify
from lxml.objectify import StringElement, IntElement, BoolElement

from taf.internal.scf.exceptions import AttributeSetterNotSupported
from taf.internal.scf.tree_object import TreeObject


class P(TreeObject):
    def __init__(self, tree=None):
        super(P, self).__init__(tree)

    def __setattr__(self, key, value):
        if key == 'value':
            if value is not None:
                if isinstance(value, bool):
                    if value:
                        string_value = 'true'
                    else:
                        string_value = 'false'
                else:
                    string_value = str(value)

                self._tree._setText(string_value)
            else:
                raise ValueError("The value of P object cannot be None.")
        else:
            try:
                super(P, self).__setattr__(key=key, value=value)
            except AttributeSetterNotSupported:
                raise AttributeSetterNotSupported("For P element you can set only 'value' attribute, please use "
                                                  "'p_element.value = x' syntax.")

    @property
    def name(self):
        name = self._tree.get('name')
        if name is not None:
            return str(name)

    @property
    def value_as_text(self):
        value = self._tree
        if value is not None:
            return value.text

    @property
    def value(self):
        value = self._tree
        if isinstance(value, StringElement):
            return str(value)
        elif isinstance(value, BoolElement):
            return repr(value) == 'True'
        elif isinstance(value, IntElement):
            return int(value)
        return self._tree

    def create(self, value, name=None, ns='raml21.xsd'):
        if value is not None:
            if isinstance(value, bool):
                if value:
                    element = objectify.BoolElement('true')
                else:
                    element = objectify.BoolElement('false')
            elif isinstance(value, int):
                element = objectify.IntElement(str(value))
            else:
                element = objectify.StringElement(value)
            element.tag = '{' + ns + '}p'
            if name:
                element.attrib['name'] = name
            self._tree = element
            return self
        raise ValueError("The value of P object cannot be None.")
